// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(this));
        vm.assume(receiver != address(c));
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, 1e30);

        vm.deal(address(c), amount);
        uint256 before = receiver.balance;
        uint256 contractBefore = address(c).balance;

        c.sendTo(receiver, amount);

        assertTrue(
            receiver.balance - before == amount && contractBefore - address(c).balance == amount,
            "sendTo must transfer exactly amount to receiver"
        );
    }
}
